L000421	\appendix
L000422	\section{Maass forms}
L000423	We give definition and basic properties of the Maass forms in this appendix.
L000424	\paragraph{Eisenstein series.} The real-analytic Eisenstein series $E_s(\tau)$ span the continuous spectrum of the Laplacian and satisfies
L000425	\begin{align}
L000426	\Delta_{\tau}E_s(\tau)=s(1-s)E_s(\tau)\,.
L000427	\end{align}
L000428	It can be written as a Poincar\'e series
L000429	\begin{align}
L000430	E_s(\tau)=\frac{1}{2}\sum_{\text{GCD}(c,d)=1}\frac{\tau_2^s}{|c\tau+d|^{2s}}\,
L000431	\end{align}
L000432	for $\text{Re}(s)>1$ and by analytic continuation for other values of complex number $s$. It has the following Fourier expansion
L000433	\begin{equation}
L000434	\begin{aligned}
L000435	E_s(\tau)=&\tau_2^s+\frac{\Lambda(1-s)}{\Lambda(s)}\tau_2^{1-s}\\
L000436	&+\frac{4\sqrt{\tau_2}}{\Lambda(s)}\sum_{n=1}^{\infty}\frac{\sigma_{1-2s}(n)}{n^{s-\frac{1}{2}}}K_{s-\frac{1}{2}}(2\pi n\tau_2)\cos(2\pi n\tau_1)\,,
L000437	\end{aligned}
L000438	\end{equation}
L000439	where $\Lambda(s)=\pi^{-s}\Gamma(s)\zeta(2s)$ is the symmetrized version of Riemann zeta function and $\sigma_s(n)$ is the divisor function defined by
L000440	\begin{align}
L000441	\sigma_s(n)=\sum_{0<l|n}l^s\,,
L000442	\end{align}
L000443	with the sum runs over all positive divisors $l$ of $n$.
L000444	
L000445	\paragraph{Maass cusp forms.} The discrete spectrum of the Laplacian is spanned by the constant mode  $\nu_0=\sqrt{3/\pi}$ and the Maass cusp forms $\nu_n(\tau)$, ($n=1,\ldots$) which satisfy
L000446	\begin{align}
L000447	\Delta_{\tau}\nu_n(\tau)=s_n(1-s_n)\nu_n(\tau)
L000448	\end{align}
L000449	where $s_n=\frac{1}{2}+\ri\,t_n$ with $t_n>0$. They satisfy
L000450	\begin{align}
L000451	\int_{-1/2}^{1/2}\nu_n(\tau)\mathrm{d}\tau_1=0\,,\quad n\ge 1\,.
L000452	\end{align}
L000453	The cusp forms can be classified by their parity under the transformation $\tau\to-\bar{\tau}$. The even and odd forms, denoted by $\nu_n^+(\tau)$ and $\nu_n^-(\tau)$ respectively, satisfy
L000454	\begin{align}
L000455	\nu_n^+(\tau)=\nu_n^+(-\bar{\tau}),\quad \nu_n^-(\tau)=-\nu_n^-(-\bar{\tau})\,.
L000456	\end{align}
L000457	They admit the following Fourier series expansions
L000458	\begin{align}
L000459	&\nu_n^+(\tau)=\sum_{j=1}^{\infty}a_j^{(n,+)}\cos(2\pi j\tau_1)\sqrt{\tau_2}K_{\ri t_n^+}(2\pi j\tau_2)\,,\\\nonumber
L000460	&\nu_n^-(\tau)=\sum_{j=1}^{\infty}a_j^{(n,-)}\sin(2\pi j\tau_1)\sqrt{\tau_2}K_{\ri t_n^-}(2\pi j\tau_2)\,.
L000461	\end{align}
L000462	The coefficients $a_j^{(n,\pm)}$ and the eigenvalues $t_n^{\pm}$ cannot be written down in a simple form, but can be determined numerically. Their explicit values can be found \emph{e.g} in \cite{terras2013harmonic}.
L000463	
L000464	
L000465	\section{Properties of integral transformation}
L000466	In this appendix, we present detailed proofs for the property of $\mathcal{T}_{\chi}$-transform in the main text.
L000467	
L000468	\vspace{0.3cm}
L000469	\paragraph{Commutativity with modular transformation.}
L000470	We first prove the action of $\mathcal{T}_{\chi}$-transform commutes with the action of modular transformation. Recall the $\mathcal{T}_{\chi}$-transform \eqref{eq:defTchi1} is defined as
L000471	\begin{align}
L000472	\mathcal{T}_{\chi}[f](\tau)=\frac{\chi}{\pi}\int_{\mathbb{H}}\frac{\rd^2\zeta}{(\text{Im}\,\zeta)^2}e^{-\chi\frac{|\tau-\zeta|^2}{\text{Im}\tau\,\text{Im}\,\zeta}}f(\zeta)
L000473	\end{align}
L000474	Note that $\chi$ does not change under modular transformation. The integral measure is invariant under modular transformation. The kernel has the following property: it is invariant under a simultaneous modular transformation $\gamma$ for $\tau$ and $\zeta$, namely
L000475	\begin{align}
L000476	\frac{|\gamma\cdot\tau-\gamma\cdot\zeta|^2}{\text{Im}(\gamma\cdot\tau)\text{Im}(\gamma\cdot\zeta)}=\frac{|\tau-\zeta|^2}{\text{Im}\,\tau\text{Im}\,\zeta}\,,
L000477	\end{align}
L000478	which can be verified by a simple computation. This leads to
L000479	\begin{align}
L000480	\frac{|\tau-\gamma^{-1}\cdot\zeta|^2}{\text{Im}(\tau)\text{Im}(\gamma^{-1}\cdot\zeta)}=\frac{|\gamma\cdot\tau-\zeta|^2}{\text{Im}(\gamma\cdot\tau)\text{Im}(\zeta)}\,.
L000481	\end{align}
L000482	Using this property, we have
L000483	\begin{align*}
L000484	\mathcal{T}_{\chi}[\gamma\cdot f](\tau)=&\,\frac{\chi}{\pi}\int_{\mathbb{H}}\frac{\rd^2\zeta}{(\text{Im}\zeta)^2}e^{-\chi\frac{|\tau-\zeta|^2}{\text{Im}\tau\,\text{Im}\zeta}}f(\gamma\cdot\zeta)\\\nonumber
L000485	=&\,\frac{\chi}{\pi}\int_{\mathbb{H}}\frac{\rd^2\zeta'}{(\text{Im}\zeta')^2}e^{-\chi\frac{|\tau-\gamma^{-1}\cdot\zeta'|^2}{\text{Im}(\tau)\text{Im}(\gamma^{-1}\cdot\zeta')}}f(\zeta')\\\nonumber
L000486	=&\,\frac{\chi}{\pi}\int_{\mathbb{H}}\frac{\rd^2\zeta'}{(\text{Im}\zeta')^2}e^{-\chi\frac{|\gamma\cdot\tau-\zeta'|^2}{\text{Im}(\gamma\cdot\tau)\text{Im}(\zeta')}}f(\zeta')\\\nonumber
L000487	=&\,\mathcal{T}_{\chi}[f](\gamma\cdot\tau)=\gamma\cdot \mathcal{T}_{\lambda}[f](\tau)
L000488	\end{align*}
L000489	which means that the two operations commute, \emph{i.e.} $[\mathcal{T}_{\chi},\gamma]=0$.
L000490	\vspace{0.3cm}
L000491	\paragraph{Action on Maass forms.}
L000492	Now we prove \eqref{eq:actionTMaass}.
L000493	For a given $f(\tau)$, its $\mathcal{T}_{\chi}$-transform is uniquely determined and satisfies the initial condition
L000494	\begin{align}
L000495	\lim_{\lambda\to 0}\mathcal{T}_{\chi}[f]=f(\tau)\,.
L000496	\end{align}
L000497	Moreover, $\mathcal{T}_{\chi}[f]$ obeys the differential flow equation involving the deformation parameter $\lambda$ \cite{Cardy:2018sdv,Aharony:2018bad}
L000498	\begin{align}
L000499	\label{eq:flowEq}
L000500	\partial_{\lambda}\mathcal{T}_{\chi}[f]=\left[\tau_2\partial_{\tau}\partial_{\bar{\tau}}+\frac{1}{2}\left(\partial_{\tau_2}-\frac{1}{\tau_2} \right)\lambda\partial_{\lambda}\right]\mathcal{T}_{\chi}[f]\,.
L000501	\end{align}
L000502	We now specialize to $f(\tau)=E_s(\tau)$. Using $\chi=\tau_2/\lambda$ and defining $\mathcal{W}_s=e^{-2\chi}\mathcal{T}_{\chi}[E_s]$, we find that $\mathcal{W}_s$ satisfies
L000503	\begin{align}
L000504	\label{eq:W}
L000505	\left(\Delta_{\tau}+\chi^2\partial_{\chi}^2-4\chi^2 \right)\mathcal{W}_s=0\,.
L000506	\end{align}
L000507	where $\Delta_{\tau}=-\tau_2^2(\partial_{\tau_1}^2+\partial_{\tau_2}^2)$ is the hyperbolic Laplacian on the Poincaré upper half-plane. Assuming a factorized ansatz $\mathcal{W}_s(\tau,\chi)=E_s(\tau)B_s(\chi)$ and using the eigenvalue equation
L000508	\begin{align}
L000509	\Delta_{\tau}E_s(\tau)=s(1-s)E_s(\tau)\,,
L000510	\end{align}
L000511	we obtain the following ordinary differential equation for $B_s(\chi)$
L000512	\begin{align}
L000513	\chi^2B''_s(\chi)-(4\chi^2+s(s-1))B_s(\chi)=0\,.
L000514	\end{align}
L000515	The general solution is
L000516	\begin{align}
L000517	B_s(\chi)=\sqrt{\chi}\left(c_1\,I_{s-\frac{1}{2}}(2\chi)+c_2\,K_{s-\frac{1}{2}}(2\chi) \right)
L000518	\end{align}
L000519	for $s(1-s)\ne 0$ and
L000520	\begin{align}
L000521	B_s(\chi)=
L000522	c_1\,e^{2\chi}+c_2\,e^{-2\chi}
L000523	\end{align}
L000524	for $s(1-s)=0$, where $I_{\nu}$ and $K_{\nu}$ are modified Bessel functions. The limit $\lambda\to 0$ corresponds to $\chi\to\infty$, and the initial condition requires
L000525	\begin{align}
L000526	\lim_{\chi\to\infty}e^{2\chi}B_s(\chi)=1\,.
L000527	\end{align}
L000528	This asymptotic behavior fixes $c_1=0$ and $c_2=2/\sqrt{\pi}$. Consequently,
L000529	\begin{align}\label{TlambdaEs}
L000530	\mathcal{T}_{\chi}[E_s]=e^{2\chi}B_s(\chi)E_s=\frac{2e^{2\chi}}{\sqrt{\pi}}\sqrt{\chi}K_{s-\frac{1}{2}}(2\chi)\,E_s(\tau)\,.
L000531	\end{align}
L000532	Uniqueness guarantees that this is indeed the $\mathcal{T}_{\lambda}$-transform of $E_s$. The proof for $\nu_n(\tau)$ follows analogously, using the eigenvalue
L000533	\begin{align}
L000534	\Delta_{\tau}\nu_n(\tau)=s_n(1-s_n)\nu_n(\tau)=(\tfrac{1}{4}+t_n^2)\nu_n(\tau)
L000535	\end{align}
L000536	we conclude that
L000537	\begin{align}
L000538	\mathcal{T}_{\chi}[\nu_n]=\frac{2e^{2\chi}}{\sqrt{\pi}}\sqrt{\chi}K_{\mathrm{i}t_n}(2\chi)\,\nu_n(\tau)\,,\quad n\geq 1.
L000539	\end{align}
L000540	The $\mathcal{T}_{\chi}$-transform of $E^r_1$ can be computed by taking proper limiting procedure.
L000541	Recall the definition of $E^r_1(\tau)$
L000542	\begin{align}
L000543	E^r_1(\tau)=\lim_{\epsilon\to 0}\left(E_{1+\epsilon}(\tau)-\frac{3}{\pi\epsilon}\right)\,,
L000544	\end{align}
L000545	plugging into \eqref{TlambdaEs}, we obtain
L000546	\begin{align}
L000547	\mathcal{T}_{\chi}[E^r_1]=&\,\lim_{\epsilon\to 0}\left(\mathcal{T}_{\chi}[E_{1+\epsilon}]-\mathcal{T}_{\chi}\left[\frac{3}{\pi\epsilon}\right]\right)\\\nonumber
L000548	=&\,\frac{2}{\sqrt{\pi}}e^{2\chi}\left(\frac{3}{\pi}\left.\sqrt{\chi}\partial_{\nu}K_{\nu}(2\chi)\right|_{\nu=1/2}+\frac{\sqrt{\pi}}{2}e^{-2\chi}E^r_1\right)\\\nonumber
L000549	=&\,E_1^r(\tau)+\frac{3}{\pi}U(1,1,4\chi)\,,
L000550	\end{align}
L000551	where in the last line we have exchanged the limit $\epsilon\to 0$ and $\mathcal{T}_{\chi}$-transform. The exchange is valid since expanding $E_s(\tau)B_s(\chi)$ at $s=1+\epsilon$, every $O(\epsilon^n)$ terms satisfies the flow equation and is modular invariant.
L000552	
