L000555	\section{Proof of the convergence of eq.~\eqref{eq:TZE}}
L000556	
L000557	In this section, we prove that the infinite sum in \eqref{eq:TZE}, i.e.
L000558	\begin{equation}\label{eq:Mtau}
L000559	M(\tau)\equiv\sum_{\gamma\in\Gamma/\Gamma_{\infty}}
L000560	\left({\rm e}^{2\chi\left(1-\sqrt{1-\frac{2\pi \tc}{12\chi}\text{Im}(\gamma\cdot\tau)} \right)}
L000561	 -1-\frac{2\pi \tc}{12}\text{Im}(\gamma\cdot\tau)\right)
L000562	\end{equation}
L000563	is convergent.
L000564	For this purpose, we spell out the range of summation,
L000565	\begin{equation}
L000566	    \Gamma/\Gamma_\infty = \{(c,d)\in\mathbb{Z}^2 \,|\, \text{GCD}(c,d) = 1\},
L000567	\end{equation}
L000568	and rewrite the infinite sum as
L000569	\begin{equation}
L000570	    M(\tau) = \sum_{\gamma:\text{GCD}(c,d)=1}
L000571	    \left({\rm e}^{2\chi\left(1-\sqrt{1-\epsilon y_\gamma} \right)}
L000572	 -1-\chi \epsilon y_\gamma\right)
L000573	\end{equation}
L000574	where $\epsilon=\pi \tc/(6\chi)$ and
L000575	\begin{equation}
L000576	    y_\gamma = \rm{Im}(\gamma\cdot\tau) = \frac{\tau_2}{|c\tau+d|^2}.
L000577	\end{equation}
L000578	If $(c,d) = (0,\pm 1)$, $y_\gamma = \tau_2$, and when $|c|,|d|$ become greater, $y_\gamma$ becomes progressively small, eventually tending to zero.
L000579	In fact, for any value of $\epsilon$, there are only finitely many $\gamma \in \Gamma/\Gamma_\infty$ such that
L000580	\begin{equation}
L000581	    |\epsilon| y_\gamma  > 1
L000582	\end{equation}
L000583	or equivalently
L000584	\begin{equation}
L000585	    |\epsilon|\tau_2 > (c\tau_1+d)^2 + c^2\tau_2^2.
L000586	\end{equation}
L000587	Let us now split the infinite sum  \eqref{eq:Mtau} to two parts, the part $M_{>}(\tau)$ over the finite subset of $\Gamma/\Gamma_\infty$,
L000588	\begin{equation}
L000589	    (\Gamma/\Gamma_\infty)_> = \{\gamma \in \Gamma/\Gamma_\infty \,|\, |\epsilon|y_\gamma>1\},
L000590	\end{equation}
L000591	which is obviously finite,
L000592	and the part $M_{<}(\tau)$ over the infinite complement $(\Gamma/\Gamma_\infty)_<$.
L000593	The summand of $M_{<}(\tau)$ can be Taylor expanded, yielding
L000594	\begin{equation}
L000595	    M_{<}(\tau)
L000596	    =\sum_{\gamma\in(\Gamma/\Gamma_\infty)_<}
L000597	    \sum_{n=2}^\infty a_n y^n_{\gamma}.
L000598	\end{equation}
L000599	The power series of $y_\gamma^n$ over $n$ has a radius of convergence $1/|\epsilon|$, and the first few coefficients are
L000600	\begin{equation}
L000601	    a_2 = \frac{\pi^2\bar{c}^2(2\chi+1)}{144\chi}, \quad a_3 = \frac{\pi ^3 \bar{c}^3 \left(4 \chi ^2+6 \chi +3\right)}{5184 \chi ^2}.
L000602	\end{equation}
L000603	As the Taylor series is absolutely convergent, we can exchange the order of summation and arrive at
L000604	\begin{align}
L000605	    M_{<}(\tau) &=\sum_{n=2}^\infty a_n\left(E_n(\tau) - \sum_{\gamma\in(\Gamma/\Gamma_\infty)_>}y_\gamma^n\right)
L000606	   \label{eq:MESer}
L000607	\end{align}
L000608	In the limit $n\rightarrow \infty$, the real-analytic Eisenstein series $E_n(\tau)$ has the asymptotic behavior
L000609	\begin{equation}
L000610	    \left(E_n(\tau) - \sum_{\gamma\in(\Gamma/\Gamma_\infty)_>}y_\gamma^n\right) \sim \mathcal{O}(y_{\gamma,<}^n),
L000611	\end{equation}
L000612	where $y_{\gamma,<}$ is the maximum member of $\{y_\gamma \,|\, \gamma\in(\Gamma/\Gamma_\infty)_<\}$, which is by definition smaller than $1/|\epsilon|$, and thus eq.~\eqref{eq:MESer} is also convergent.
